export function getPhotoStoryPostBySlug(slug) {
  return photoStoryPosts.find((post) => post.slug === slug) ?? null
}

export function getPhotoStoryAdjacent(slug) {
  const index = photoStoryPosts.findIndex((post) => post.slug === slug)
  if (index < 0) return { prev: null, next: null }
  return {
    prev: index > 0 ? photoStoryPosts[index - 1] : null,
    next: index < photoStoryPosts.length - 1 ? photoStoryPosts[index + 1] : null,
  }
}

export function getPhotoStoryRelated(slug, limit = 4) {
  return photoStoryPosts.filter((post) => post.slug !== slug).slice(0, limit)
}

